UPDATE partners SET description = 'AlphaBag의 공식 거래소 파트너. Binance 플랫폼을 통한 원활한 자산 이동 및 AlphaBag 투자 플랜과의 직접 연동을 지원합니다.' WHERE name = 'Binance';

UPDATE partners SET description = 'AlphaBag 글로벌 거래소 파트너. OKX의 Web3 지갑 및 DeFi 인프라를 활용하여 AlphaBag 투자자에게 확장된 유동성을 제공합니다.' WHERE name = 'OKX';

UPDATE partners SET description = 'AlphaBag DeFi 인프라 파트너. Uniswap V3 프로토콜을 통한 분산형 유동성 공급으로 AlphaBag 포트폴리오의 DEX 전략을 지원합니다.' WHERE name = 'Uniswap';

UPDATE partners SET description = 'AlphaBag 대출·스테이킹 파트너. Aave 프로토콜 기반의 담보 대출 및 이자 수익 전략이 AlphaBag Self 컬렉션에 통합되어 있습니다.' WHERE name = 'Aave';

UPDATE partners SET description = 'AlphaBag 데이터 인프라 파트너. Chainlink의 분산형 오라클 네트워크를 통해 AlphaBag 투자 플랜의 가격 피드 및 수익률 데이터를 실시간으로 검증합니다.' WHERE name = 'Chainlink';

UPDATE partners SET description = 'AlphaBag Layer2 확장성 파트너. Polygon 네트워크를 통한 저비용·고속 트랜잭션으로 AlphaBag 투자자의 가스비 부담을 최소화합니다.' WHERE name = 'Polygon';

UPDATE partners SET description = 'AlphaBag NFT 마켓플레이스 파트너. OpenSea와의 연동을 통해 AlphaBag NFT 컬렉션 및 멤버십 토큰의 2차 거래 시장을 지원합니다.' WHERE name = 'OpenSea';

UPDATE partners SET description = 'AlphaBag 시장 데이터 파트너. CoinGecko의 실시간 시세 및 온체인 데이터를 AlphaBag 플랫폼의 투자 분석 및 수익률 계산에 활용합니다.' WHERE name = 'CoinGecko';

